// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/dashboard", wrapper.GetDashboard)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/services", wrapper.ListServices)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/metrics", wrapper.GetMetrics)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/alerts", wrapper.ListAlerts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/sysadmin/alerts/{id}/ack", wrapper.AcknowledgeAlert)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/thresholds", wrapper.ListThresholds)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/sysadmin/thresholds", wrapper.PutThresholds)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/dlq", wrapper.ListDeadLetters)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/dlq/summary", wrapper.GetDeadLetterSummary)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/sysadmin/dlq/{sequence}/ack", wrapper.AcknowledgeDeadLetter)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/events", wrapper.ListReceivedEvents)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/metrics", wrapper.GetShopMetrics)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/alerts", wrapper.ListShopAlerts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/alerts/{id}/ack", wrapper.AcknowledgeShopAlert)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/dlq", wrapper.GetShopDeadLetterSummary)
	})

	return r
}

