// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListShopAlerts List my shop's alerts
	// (GET /admin/alerts)
	ListShopAlerts(ctx context.Context, request ListShopAlertsRequestObject) (ListShopAlertsResponseObject, error)
	// AcknowledgeShopAlert Acknowledge one of my shop's alerts
	// (POST /admin/alerts/{id}/ack)
	AcknowledgeShopAlert(ctx context.Context, request AcknowledgeShopAlertRequestObject) (AcknowledgeShopAlertResponseObject, error)
	// GetShopDeadLetterSummary Count my shop's unacknowledged dead letters
	// (GET /admin/dlq)
	GetShopDeadLetterSummary(ctx context.Context, request GetShopDeadLetterSummaryRequestObject) (GetShopDeadLetterSummaryResponseObject, error)
	// GetShopMetrics Query a counter for my shop
	// (GET /admin/metrics)
	GetShopMetrics(ctx context.Context, request GetShopMetricsRequestObject) (GetShopMetricsResponseObject, error)
	// ListAlerts List alerts
	// (GET /sysadmin/alerts)
	ListAlerts(ctx context.Context, request ListAlertsRequestObject) (ListAlertsResponseObject, error)
	// AcknowledgeAlert Acknowledge an alert
	// (POST /sysadmin/alerts/{id}/ack)
	AcknowledgeAlert(ctx context.Context, request AcknowledgeAlertRequestObject) (AcknowledgeAlertResponseObject, error)
	// GetDashboard Platform dashboard
	// (GET /sysadmin/dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// ListDeadLetters List dead letters
	// (GET /sysadmin/dlq)
	ListDeadLetters(ctx context.Context, request ListDeadLettersRequestObject) (ListDeadLettersResponseObject, error)
	// GetDeadLetterSummary Count unacknowledged dead letters
	// (GET /sysadmin/dlq/summary)
	GetDeadLetterSummary(ctx context.Context, request GetDeadLetterSummaryRequestObject) (GetDeadLetterSummaryResponseObject, error)
	// AcknowledgeDeadLetter Acknowledge a dead letter
	// (POST /sysadmin/dlq/{sequence}/ack)
	AcknowledgeDeadLetter(ctx context.Context, request AcknowledgeDeadLetterRequestObject) (AcknowledgeDeadLetterResponseObject, error)
	// ListReceivedEvents List received events
	// (GET /sysadmin/events)
	ListReceivedEvents(ctx context.Context, request ListReceivedEventsRequestObject) (ListReceivedEventsResponseObject, error)
	// GetMetrics Query a counter
	// (GET /sysadmin/metrics)
	GetMetrics(ctx context.Context, request GetMetricsRequestObject) (GetMetricsResponseObject, error)
	// ListServices List services and their health
	// (GET /sysadmin/services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// ListThresholds List alert thresholds
	// (GET /sysadmin/thresholds)
	ListThresholds(ctx context.Context, request ListThresholdsRequestObject) (ListThresholdsResponseObject, error)
	// PutThresholds Set an alert threshold
	// (PUT /sysadmin/thresholds)
	PutThresholds(ctx context.Context, request PutThresholdsRequestObject) (PutThresholdsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

